use vstd::prelude::*;

verus! {

/// Spec-level model of `hstack`: concatenation of two sequences.
spec fn hstack_spec(a: Seq<f32>, b: Seq<f32>) -> Seq<f32> {
    a + b
}

fn hstack(a: Vec<f32>, b: Vec<f32>) -> (out: Vec<f32>)
    ensures
        // Result is the concatenation of the two inputs (in order)
        out@ == hstack_spec(a@, b@),
        // Length is the sum of lengths
        out@.len() == a@.len() + b@.len(),
{
    let mut out = Vec::with_capacity(a.len() + b.len());

    out.extend_from_slice(&a);
    assert(out@ == a@);
    assert(out@.len() == a@.len());

    out.extend_from_slice(&b);
    assert(out@ == a@ + b@);

    out
}

} // verus!
